import { useState, useEffect } from 'react';
import { useSearchParams, useNavigate } from 'react-router-dom';
import Button from '../components/Button';

export default function QuizPage() {
  const [searchParams] = useSearchParams();
  const navigate = useNavigate();
  const domain = searchParams.get('domain') || 'web-development';
  
  const [questions, setQuestions] = useState([]);
  const [selected, setSelected] = useState({});
  const [submitted, setSubmitted] = useState(false);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchQuestions = async () => {
      setLoading(true);
      try {
        const res = await fetch("http://localhost:5000/api/quiz/generate", {
          method: "POST",
          headers: { "Content-Type": "application/json" },
          body: JSON.stringify({ domain })
        });
        const data = await res.json();
        setQuestions(data);
      } catch (err) {
        console.error("Fetch Error:", err);
      } finally {
        setLoading(false);
      }
    };
    fetchQuestions();
  }, [domain]);

  // 🔥 CLEANING LOGIC: Strips "a) ", "1. ", etc.
  const cleanStr = (str) => {
    if (!str) return "";
    return str.replace(/^[a-z0-9][\s).:-]+/i, "").trim().toLowerCase();
  };

  const calculateScore = () => {
    return questions.reduce((acc, q, idx) => {
      const userAns = cleanStr(selected[idx]);
      const correctAns = cleanStr(q.answer);
      return acc + (userAns === correctAns ? 1 : 0);
    }, 0);
  };

  if (loading) return (
    <div className="flex flex-col items-center justify-center p-20 space-y-4">
      <div className="animate-spin rounded-full h-10 w-10 border-b-2 border-blue-500"></div>
      <p className="text-slate-600 font-medium">Generating your {domain} quiz...</p>
    </div>
  );

  const score = calculateScore();

  return (
    <div className="max-w-4xl mx-auto p-4 space-y-6">
      <div className="bg-white rounded-3xl p-8 border shadow-sm dark:bg-slate-800 dark:border-slate-700">
        <h2 className="text-3xl font-bold capitalize mb-2 dark:text-white">
          {domain.replace(/-/g, ' ')} Assessment
        </h2>
        <p className="text-slate-500 mb-8">Test your knowledge to build your roadmap.</p>
        
        <div className="space-y-8">
          {questions.map((q, idx) => (
            <div key={idx} className="p-6 rounded-2xl bg-slate-50 border dark:bg-slate-900 dark:border-slate-700">
              <p className="font-semibold text-lg mb-4 dark:text-slate-100">{idx + 1}. {q.question}</p>
              <div className="grid gap-3 sm:grid-cols-2">
                {q.options.map((opt) => {
                  const isCorrect = submitted && cleanStr(opt) === cleanStr(q.answer);
                  const isSelected = selected[idx] === opt;

                  return (
                    <button
                      key={opt}
                      disabled={submitted}
                      onClick={() => setSelected(prev => ({ ...prev, [idx]: opt }))}
                      className={`p-4 text-left border rounded-xl transition-all font-medium ${
                        isSelected 
                          ? 'bg-blue-600 text-white border-blue-600' 
                          : 'bg-white hover:border-blue-300 dark:bg-slate-800 dark:text-slate-300'
                      } ${isCorrect ? 'ring-4 ring-green-400 bg-green-50 text-green-900 border-green-500' : ''}`}
                    >
                      {opt}
                    </button>
                  );
                })}
              </div>
            </div>
          ))}
        </div>

        <div className="mt-8 border-t pt-6">
          {!submitted ? (
            <Button 
              onClick={() => setSubmitted(true)} 
              disabled={Object.keys(selected).length < questions.length}
              className="w-full sm:w-auto px-10 py-4"
            >
              Submit Results
            </Button>
          ) : (
            <div className="flex flex-col sm:flex-row items-center justify-between gap-4">
              <div className="text-3xl font-bold text-teal-600">
                Score: {score} / {questions.length}
              </div>
              <Button onClick={() => navigate(`/roadmap/${domain}`)} className="px-8 py-4">
                Continue to Roadmap →
              </Button>
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
